#include <iostream>

int main() {
    // Bucle for: inicialización; condición; incremento
    for (int i = 1; i <= 5; i++) {
        if (i == 3) continue; // Salta el 3
        std::cout << i << " ";
    }

    std::cout << "\n";

    // do-while: garantizado al menos 1 paso
    int intentos = 0;
    do {
        intentos++;
    } while (intentos < 3);

    std::cout << "Intentos realizados: " << intentos << std::endl;
    return 0;
}

#include <iostream>

// Paso por referencia usando &
void intercambiar(int &a, int &b) {
    int temporal = a;
    a = b;
    b = temporal;
}

int main() {
    int x = 10, y = 20;
    intercambiar(x, y);
    std::cout << "x: " << x << ", y: " << y << std::endl;
    // Imprime: x: 20, y: 10
    return 0;
}

