public class Termostato {
    private double temperatura = 20.0;

    public double getTemperatura() {
        return this.temperatura;
    }

    public void setTemperatura(double nuevaTemp) {
        // Validación de invariante de negocio
        if (nuevaTemp >= 10.0 && nuevaTemp <= 35.0) {
            this.temperatura = nuevaTemp;
        } else {
            System.out.println("Temperatura fuera de rango permitido");
        }
    }
}

